CREATE TABLE orders (
  order_id      NUMBER PRIMARY KEY,
  customer_name VARCHAR2(50),
  amount        NUMBER(10,2),
  status        VARCHAR2(20),
  order_date    DATE
);

CREATE TABLE order_daily_summary (
  summary_date  DATE PRIMARY KEY,
  order_count   NUMBER,
  total_amount  NUMBER(12,2),
  created_at    TIMESTAMP DEFAULT SYSTIMESTAMP
);

INSERT INTO orders VALUES (1, 'Asha',  1200, 'PAID',      TRUNC(SYSDATE) - 1 + 10/24);
INSERT INTO orders VALUES (2, 'Ravi',   850, 'PAID',      TRUNC(SYSDATE) - 1 + 15/24);
INSERT INTO orders VALUES (3, 'Meera',  400, 'CANCELLED', TRUNC(SYSDATE) - 120);
INSERT INTO orders VALUES (4, 'John',   990, 'CANCELLED', TRUNC(SYSDATE) - 5);
COMMIT;

CREATE OR REPLACE PROCEDURE build_daily_summary AS
  l_day DATE := TRUNC(SYSDATE) - 1;
BEGIN
  DELETE FROM order_daily_summary WHERE summary_date = l_day;

  INSERT INTO order_daily_summary (summary_date, order_count, total_amount)
  SELECT l_day, COUNT(*), NVL(SUM(amount), 0)
    FROM orders
   WHERE order_date >= l_day
     AND order_date <  l_day + 1;

  COMMIT;
END;
/

CREATE OR REPLACE PROCEDURE purge_cancelled_orders (p_days IN NUMBER) AS
BEGIN
  DELETE FROM orders
   WHERE status = 'CANCELLED'
     AND order_date < SYSDATE - p_days;
  COMMIT;
END;
/

SET SERVEROUTPUT ON
DECLARE
  l_start TIMESTAMP WITH TIME ZONE :=
    TO_TIMESTAMP_TZ('2026-11-10 10:00:00 Asia/Kolkata',
                    'YYYY-MM-DD HH24:MI:SS TZR');
  l_after TIMESTAMP WITH TIME ZONE := l_start;
  l_next  TIMESTAMP WITH TIME ZONE;
BEGIN
  FOR i IN 1 .. 5 LOOP
    DBMS_SCHEDULER.EVALUATE_CALENDAR_STRING(
      calendar_string   => 'FREQ=WEEKLY;BYDAY=MON,TUE,WED,THU,FRI;BYHOUR=9;BYMINUTE=30;BYSECOND=0',
      start_date        => l_start,
      return_date_after => l_after,
      next_run_date     => l_next);
    DBMS_OUTPUT.PUT_LINE(TO_CHAR(l_next, 'DY DD-MON-YYYY HH24:MI TZR'));
    l_after := l_next;
  END LOOP;
END;
/

-- Run now, in your own session, to test it
EXEC DBMS_SCHEDULER.RUN_JOB('DAILY_ORDER_SUMMARY');

-- Run now in the background, like a normal scheduled run
EXEC DBMS_SCHEDULER.RUN_JOB('DAILY_ORDER_SUMMARY', use_current_session => FALSE);

-- Change the schedule to 2:30 AM
BEGIN
  DBMS_SCHEDULER.SET_ATTRIBUTE(
    name      => 'DAILY_ORDER_SUMMARY',
    attribute => 'repeat_interval',
    value     => 'FREQ=DAILY;BYHOUR=2;BYMINUTE=30;BYSECOND=0');
END;
/

-- Pause and resume
EXEC DBMS_SCHEDULER.DISABLE('DAILY_ORDER_SUMMARY');
EXEC DBMS_SCHEDULER.ENABLE('DAILY_ORDER_SUMMARY');

-- Stop a running job, then drop it
EXEC DBMS_SCHEDULER.STOP_JOB('DAILY_ORDER_SUMMARY');
EXEC DBMS_SCHEDULER.DROP_JOB('DAILY_ORDER_SUMMARY');

